(351, 9, 13, NULL, 'Đặc tả luồng thao tác và phân quyền trên bảng công việc', 'Phần việc độc lập được tách từ thiết kế chi tiết của Plan AI. Đầu ra gồm đặc tả luồng thao tác, ma trận quyền và tiêu chí kiểm tra có thể review riêng.', 23, 'done', 'high', '2026-06-29', '2026-07-04', 6.00, '2026-07-04 17:00:00', '2026-06-29 09:00:00', '2026-07-04 17:00:00'),
(352, 9, 13, NULL, 'Xây giao diện bảng công việc và thao tác kéo thả', 'Phần việc độc lập được tách từ triển khai luồng chính của Plan AI. Đầu ra là giao diện bảng việc và thao tác kéo thả có thể kiểm thử riêng.', 23, 'done', 'high', '2026-07-05', '2026-07-10', 7.00, '2026-07-10 17:00:00', '2026-07-05 09:00:00', '2026-07-10 17:00:00'),
