(370, 10, 15, 82, 'Xây API hồ sơ nhân sự và số dư nghỉ phép', 'Task con của hạng mục cốt lõi People Hub. Đầu ra là API hồ sơ và số dư nghỉ có kiểm tra dữ liệu đầu vào.', 32, 'in_progress', 'low', '2026-08-16', '2026-08-18', 8.00, NULL, '2026-08-06 09:00:00', '2026-08-10 18:00:00'),
(371, 10, 15, 82, 'Xây API gửi đơn và chuyển bước phê duyệt', 'Task con của hạng mục cốt lõi People Hub. Đầu ra là API gửi đơn và chuyển bước phê duyệt theo đúng ma trận quyền.', 32, 'in_progress', 'low', '2026-08-11', '2026-08-15', 8.00, NULL, '2026-08-06 09:00:00', '2026-08-10 18:00:00'),
(372, 10, 15, 82, 'Kết nối giao diện hồ sơ với luồng duyệt đơn', 'Task con của hạng mục cốt lõi People Hub. Đầu ra là giao diện hồ sơ kết nối được với luồng gửi và duyệt đơn.', 32, 'in_progress', 'critical', '2026-08-06', '2026-08-10', 6.00, NULL, '2026-08-06 09:00:00', '2026-08-10 18:00:00'),
(373, 10, 15, 83, 'Tích hợp giao diện tạo đơn nghỉ với API', 'Task con của giai đoạn tích hợp People Hub. Đầu ra là form tạo đơn hoạt động với API và hiển thị lỗi đầu vào rõ ràng.', 32, 'todo', 'high', '2026-08-22', '2026-08-26', 6.00, NULL, '2026-08-19 09:00:00', '2026-08-19 18:00:00'),
(374, 10, 15, 83, 'Tích hợp màn hình quản lý phê duyệt đơn', 'Task con của giai đoạn tích hợp People Hub. Đầu ra là màn hình quản lý duyệt, từ chối và chuyển người xử lý.', 32, 'todo', 'high', '2026-08-27', '2026-08-31', 6.00, NULL, '2026-08-19 09:00:00', '2026-08-19 18:00:00'),
(375, 10, 15, 83, 'Chuẩn bị dữ liệu và kịch bản demo nghỉ phép', 'Task con của giai đoạn tích hợp People Hub. Đầu ra là dữ liệu mẫu và kịch bản demo bao phủ luồng phê duyệt nhiều cấp.', 32, 'todo', 'high', '2026-08-19', '2026-08-21', 6.00, NULL, '2026-08-19 09:00:00', '2026-08-19 18:00:00'),
(376, 10, 15, 84, 'Kiểm thử quyền truy cập và quy trình phê duyệt', 'Task con của kiểm thử People Hub. Đầu ra là kết quả kiểm thử quyền truy cập và các bước phê duyệt theo vai trò.', 32, 'todo', 'medium', '2026-09-01', '2026-09-08', 6.00, NULL, '2026-09-01 09:00:00', '2026-09-01 18:00:00'),
(377, 10, 15, 84, 'Đối soát quota nghỉ và lịch sử chuyển bước', 'Task con của đối soát People Hub. Đầu ra là kết quả so khớp quota nghỉ, trạng thái đơn và lịch sử chuyển bước.', 32, 'todo', 'medium', '2026-09-08', '2026-09-13', 6.00, NULL, '2026-09-01 09:00:00', '2026-09-01 18:00:00'),
(378, 10, 15, 330, 'Ghi nhận lịch sử chuyển bước phê duyệt', 'Task con của API lịch sử phê duyệt. Đầu ra là timeline lưu đúng bước trước, bước sau, người thao tác và thời điểm.', 32, 'in_progress', 'critical', '2026-08-09', '2026-08-18', 6.00, NULL, '2026-08-09 09:00:00', '2026-08-10 18:00:00'),
(379, 10, 15, 330, 'Lưu người duyệt hiện tại và thời điểm xử lý', 'Task con của API lịch sử phê duyệt. Đầu ra là người duyệt hiện tại và mốc xử lý được cập nhật nhất quán sau mỗi bước.', 32, 'in_progress', 'high', '2026-08-09', '2026-08-18', 6.00, NULL, '2026-08-09 09:00:00', '2026-08-10 18:00:00');
