-- Normalize Plan AI (Agile): split every task over 8 hours into meaningful flat tasks.
-- Existing task IDs are retained for the first deliverable so logwork/history stays attached.
UPDATE `tasks`
SET
  `description` = CASE `id`
    WHEN 70 THEN REPLACE(`description`, 'Thiết kế chi tiết cho dựng khung dự án và bảng công việc', 'Thiết kế mô hình dữ liệu dự án và bảng công việc')
    WHEN 71 THEN REPLACE(`description`, 'Triển khai luồng chính của dựng khung dự án và bảng công việc', 'Xây API quản lý dự án và danh sách công việc')
    WHEN 72 THEN REPLACE(`description`, 'Kiểm thử và nghiệm thu dựng khung dự án và bảng công việc', 'Kiểm thử luồng tạo và cập nhật dự án')
    WHEN 74 THEN REPLACE(`description`, 'Hoàn thiện chức năng chính của hoàn thiện tạo việc và giao người nhận', 'Hoàn thiện form tạo việc và kiểm tra dữ liệu')
    WHEN 75 THEN REPLACE(`description`, 'Ghép giao diện và dịch vụ cho hoàn thiện tạo việc và giao người nhận', 'Kết nối giao diện tạo việc với API')
    WHEN 76 THEN REPLACE(`description`, 'Sửa lỗi ưu tiên cao của hoàn thiện tạo việc và giao người nhận', 'Sửa lỗi tạo việc và dữ liệu bắt buộc')
    WHEN 77 THEN REPLACE(`description`, 'Ổn định luồng chính của bảng việc và phân quyền', 'Ổn định kiểm tra quyền thao tác trên bảng việc')
    WHEN 78 THEN REPLACE(`description`, 'Chạy hồi quy bộ lọc, quyền và danh sách công việc', 'Chạy hồi quy phân quyền và chuyển trạng thái')
    WHEN 338 THEN REPLACE(`description`, 'Làm bộ lọc theo tag và người theo dõi', 'Lọc công việc theo tag')
    WHEN 340 THEN REPLACE(`description`, 'Theo dõi phụ thuộc giữa task cha và task con', 'Xây liên kết phụ thuộc giữa task cha và task con')
    WHEN 341 THEN REPLACE(`description`, 'Tách checklist mẫu khi tạo task', 'Chuẩn hóa cấu trúc checklist mẫu khi tạo task')
    WHEN 343 THEN REPLACE(`description`, 'Chuẩn hóa rule đổi trạng thái và nhắc việc', 'Chuẩn hóa điều kiện chuyển trạng thái công việc')
    WHEN 344 THEN REPLACE(`description`, 'Bổ sung phân quyền theo vai trò trên bảng việc', 'Áp dụng quyền xem bảng việc theo vai trò')
    WHEN 347 THEN REPLACE(`description`, 'Phát triển liên kết phụ thuộc giữa task cha con', 'Xây API liên kết phụ thuộc giữa task')
    ELSE `description`
  END,
  `title` = CASE `id`
    WHEN 70 THEN 'Thiết kế mô hình dữ liệu dự án và bảng công việc'
    WHEN 71 THEN 'Xây API quản lý dự án và danh sách công việc'
    WHEN 72 THEN 'Kiểm thử luồng tạo và cập nhật dự án'
    WHEN 74 THEN 'Hoàn thiện form tạo việc và kiểm tra dữ liệu'
    WHEN 75 THEN 'Kết nối giao diện tạo việc với API'
    WHEN 76 THEN 'Sửa lỗi tạo việc và dữ liệu bắt buộc'
    WHEN 77 THEN 'Ổn định kiểm tra quyền thao tác trên bảng việc'
    WHEN 78 THEN 'Chạy hồi quy phân quyền và chuyển trạng thái'
    WHEN 338 THEN 'Lọc công việc theo tag'
    WHEN 340 THEN 'Xây liên kết phụ thuộc giữa task cha và task con'
    WHEN 341 THEN 'Chuẩn hóa cấu trúc checklist mẫu khi tạo task'
    WHEN 343 THEN 'Chuẩn hóa điều kiện chuyển trạng thái công việc'
    WHEN 344 THEN 'Áp dụng quyền xem bảng việc theo vai trò'
    WHEN 347 THEN 'Xây API liên kết phụ thuộc giữa task'
    ELSE `title`
  END,
  `estimated_hours` = CASE `id`
    WHEN 70 THEN 6.00
    WHEN 71 THEN 7.00
    WHEN 72 THEN 5.00
    WHEN 74 THEN 6.00
    WHEN 75 THEN 8.00
    WHEN 76 THEN 6.00
    WHEN 77 THEN 6.00
    WHEN 78 THEN 5.00
    WHEN 338 THEN 5.00
    WHEN 340 THEN 6.00
    WHEN 341 THEN 5.00
    WHEN 342 THEN 5.00
    WHEN 343 THEN 4.50
    WHEN 344 THEN 5.00
    WHEN 347 THEN 5.00
    ELSE `estimated_hours`
  END,
  `parent_task_id` = CASE WHEN `id` = 342 THEN NULL ELSE `parent_task_id` END
WHERE `project_id` = 9
  AND `id` IN (70, 71, 72, 74, 75, 76, 77, 78, 338, 340, 341, 342, 343, 344, 347);


-- Normalize People Hub (Waterfall): decompose every leaf over 8 hours into
-- reviewable subtasks. Parent ET is derived from leaves after the hierarchy is complete.

-- Only the two People Hub parent tasks shown in the WBS leave ET to the roll-up algorithm.
UPDATE `tasks`
SET `estimated_hours` = NULL
WHERE `project_id` = 10
  AND `id` IN (80, 81);




SET FOREIGN_KEY_CHECKS = 1;
